import{_ as t,o as d,c as o,ag as r}from"./chunks/framework.8tqBsFWt.js";const m=JSON.parse('{"title":"Time Tracking Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/time.md","filePath":"reference/tools/time.md"}'),n={name:"reference/tools/time.md"};function s(a,e,i,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="time-tracking-tools" tabindex="-1">Time Tracking Tools <a class="header-anchor" href="#time-tracking-tools" aria-label="Permalink to &quot;Time Tracking Tools&quot;">​</a></h1><hr><h2 id="log_time" tabindex="-1">log_time <a class="header-anchor" href="#log_time" aria-label="Permalink to &quot;log_time {#log_time}&quot;">​</a></h2><p>Record hours on a project.</p><p><strong>Writes to</strong>: <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td>✅</td><td>Always the sender&#39;s Slack ID</td></tr><tr><td><code>project</code></td><td>string</td><td>✅</td><td>Project name (must match exactly)</td></tr><tr><td><code>task</code></td><td>string</td><td>✅</td><td>Task type — Development, Design, QA, etc.</td></tr><tr><td><code>hours</code></td><td>string</td><td>✅</td><td>Format: <code>&quot;4h 30m&quot;</code></td></tr><tr><td><code>date</code></td><td>string</td><td></td><td><code>YYYY-MM-DD</code> — defaults to today</td></tr><tr><td><code>notes</code></td><td>string</td><td></td><td>Optional context</td></tr><tr><td><code>slack_user_id</code></td><td>string</td><td></td><td>Log for another user — Manager/Owner only</td></tr><tr><td><code>person</code></td><td>string</td><td></td><td>Name-based lookup (less reliable than <code>slack_user_id</code>)</td></tr><tr><td><code>allocation_id</code></td><td>integer</td><td></td><td>Names the specific envelope this entry belongs to, when a person holds several envelopes on the same project and task. <strong>Console-only</strong> — not in Slack&#39;s tool schema.</td></tr></tbody></table><p><strong>Business rules:</strong></p><ul><li>Task is always required — VERA will ask if missing</li><li>User can only log for themselves unless Manager/Owner</li><li>When logging for an <code>@mention</code>, use <code>slack_user_id</code> not <code>person</code></li><li>Returns entry <code>id</code> on success: &quot;Logged 4h on Nike Rebrand (Development) (ID: 42)&quot;</li></ul><p><strong>Envelope attribution (optional, issue #2044):</strong> <code>allocation_id</code> lets an entry name the exact envelope it belongs to, so several envelopes sharing a person, project, and task can each carry their own logged hours instead of one merged total. When supplied it is validated against four things — the envelope exists, is active, belongs to the person the time is being logged <em>for</em> (not the requester — a manager may log on someone&#39;s behalf), and is on the resolved project — any mismatch fails with <code>❌ Failed: ...</code> and nothing is recorded. Omitted, an entry behaves exactly as it always has. <strong>This parameter is deliberately absent from Slack&#39;s tool schema</strong> — VERA has no reliable way to guess which envelope a spoken request means when several match; Slack instead offers a numbered menu for this case in a later phase of the same arc. Set only from the web console today.</p><p><strong>Example:</strong></p><blockquote><p>&quot;Log 4h 30m on Nike Rebrand for development&quot; &quot;Log 2 hours for @alice on Acme project — design&quot;</p></blockquote><hr><h2 id="get_time_entries" tabindex="-1">get_time_entries <a class="header-anchor" href="#get_time_entries" aria-label="Permalink to &quot;get_time_entries {#get_time_entries}&quot;">​</a></h2><p>Retrieve and filter time entries.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>02. Projects</code>, <code>03. Users</code>, <code>05. Tasks</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td>Controls what data is returned</td></tr><tr><td><code>slack_user_id</code></td><td>string</td><td>Filter by person (Slack ID — preferred)</td></tr><tr><td><code>person</code></td><td>string</td><td>Filter by person name</td></tr><tr><td><code>project_name</code></td><td>string</td><td>Filter by project</td></tr><tr><td><code>task_name</code></td><td>string</td><td>Filter by task type</td></tr><tr><td><code>start_date</code></td><td>string</td><td><code>YYYY-MM-DD</code> — range start</td></tr><tr><td><code>end_date</code></td><td>string</td><td><code>YYYY-MM-DD</code> — range end</td></tr></tbody></table><p><strong>Permission rules:</strong></p><ul><li>Owners see all entries</li><li>Managers see entries for their assigned projects</li><li>Users see only their own entries</li></ul><p><strong>Note:</strong> When querying for an <code>@mention</code> (e.g. &quot;show @alice&#39;s time&quot;), always pass <code>slack_user_id</code> rather than <code>person</code>. Name matching can fail if display names differ from stored names.</p><hr><h2 id="hours_this_week" tabindex="-1">hours_this_week <a class="header-anchor" href="#hours_this_week" aria-label="Permalink to &quot;hours_this_week {#hours_this_week}&quot;">​</a></h2><p>Sum of hours logged this week for a user.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td></td></tr><tr><td><code>slack_user_id</code></td><td>string</td><td>For querying another user (Manager/Owner)</td></tr></tbody></table><p>Week boundaries are calculated in the tenant&#39;s configured timezone.</p><hr><h2 id="edit_entry" tabindex="-1">edit_entry <a class="header-anchor" href="#edit_entry" aria-label="Permalink to &quot;edit_entry {#edit_entry}&quot;">​</a></h2><p>Update the hours or notes on a time entry.</p><p><strong>Updates</strong>: <code>01. Time Entries</code> (full row rewrite A:H)</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td>✅</td><td></td></tr><tr><td><code>id</code></td><td>integer</td><td>✅</td><td>Entry ID (from log confirmation or get_time_entries)</td></tr><tr><td><code>new_hours</code></td><td>string</td><td></td><td>New hours value — format <code>&quot;4h 30m&quot;</code></td></tr><tr><td><code>new_notes</code></td><td>string</td><td></td><td>New notes</td></tr><tr><td><code>new_date</code></td><td>string</td><td></td><td><code>YYYY-MM-DD</code>. Moves the entry to a different date (issue #2220). Omit to leave the date unchanged — a future date is accepted, same as <code>log_time</code>. The entry&#39;s project is never changed by a date move.</td></tr></tbody></table><p><strong>Permission</strong>: Owners and admins can edit any entry. Users can edit only their own. Managers can edit their own entry, or move <strong>only the date</strong> on someone else&#39;s entry when they are PM of record for that project — sending any other field (hours/task/notes) in that same request is refused entirely, with nothing written. A date move onto a company holiday is recorded the same way a <code>log_time</code> entry on a holiday is; a move outside a Retainer/Agile period child&#39;s own window is refused rather than moved to a different period.</p><hr><h2 id="delete_entry" tabindex="-1">delete_entry <a class="header-anchor" href="#delete_entry" aria-label="Permalink to &quot;delete_entry {#delete_entry}&quot;">​</a></h2><p>Permanently delete a time entry.</p><p><strong>Deletes from</strong>: <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>string</td><td>✅</td><td></td></tr><tr><td><code>id</code></td><td>integer</td><td>✅</td><td>Entry ID to delete</td></tr></tbody></table><p><strong>Permission</strong>: Owners can delete any entry. Users can only delete their own.</p><blockquote><p>Deletion is permanent. There is no undo. VERA will confirm the action before deleting.</p></blockquote>',43)])])}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
